package parse

import (
 \"testing\"
 \"github.com/gravitational/trace\"
 \"github.com/stretchr/testify/require\"
)

func TestNestedExpressionAndValidation(t *testing.T) {
 expr, err := NewExpression("'`pre-{{regexp.replace(email.local(external.email), "''^([''^+]+).*$", "$1")}}-post`)
 require.NoError(t, err)
 values, err := expr.Interpolate(map[string][]string{"email": {"alice+tag@example.com", "bob@example.com"}}, func(ns, name string) error {
  if ns != "external" || name != "email" { return trace.BadParameter("unsupported variable %q", name) }; return nil
 })
