func splitTemplate(value string) []string {
	start := strings.Index(value, "{{")
	if start < 0 || strings.ContainsAny(value[:start], "{}") {
		return nil
	}
	quoted, escaped := byte(0), false
	for i := start + 2; i < len(value)-1; i++ {
		c := value[i]
		if quoted != 0 {
			if escaped {
				escaped = false
			} else if c == '\\' && quoted == '"' {
				escaped = true
			} else if c == quoted {
				quoted = 0
			}
			continue
		}
		if c == '"' || c == '`' {
			quoted = c
			continue
		}
		if value[i:i+2] == "{{" {
			return nil
		}
		if value[i:i+2] == "}}" {
			if strings.ContainsAny(value[i+2:], "{}") {
				return nil
			}
			return []string{value[:start], value[start+2 : i], value[i+2:]}
		}
	}
	return nil
}

