// NewMatcher parses a matcher expression. Currently supported expressions:
// - string literal: `foo`
// - wildcard expression: `*` or `foo*bar`
// - regexp expression: `^foo$`
// - regexp function calls:
//   - positive match: `{{regexp.match("foo.*")}}`
//   - negative match: `{{regexp.not_match("foo.*")}}`
//
// These expressions do not support variable interpolation (e.g.
// `{{internal.logins}}`), like Expression does.
type MatchExpression struct {
	prefix, suffix string
	expr           Expr
}

func (m *MatchExpression) Match(in string) bool {
	if !strings.HasPrefix(in, m.prefix) || !strings.HasSuffix(in, m.suffix) || len(in) < len(m.prefix)+len(m.suffix) {
		return false
	}
	middle := in[len(m.prefix) : len(in)-len(m.suffix)]
	result, err := m.expr.Evaluate(EvaluateContext{MatcherInput: middle})
	return err == nil && result.(bool)
}

func NewMatcher(value string) (Matcher, error) {
	value = strings.TrimSpace(value)
	match := splitTemplate(value)
	if match == nil {
		if strings.Contains(value, "{{") || strings.Contains(value, "}}") || strings.ContainsAny(value, "{}") {
			return nil, trace.BadParameter("malformed template usage in %q", value)
		}
		raw := value
		if !strings.HasPrefix(raw, "^") || !strings.HasSuffix(raw, "$") {
			raw = "^" + utils.GlobToRegexp(raw) + "$"
		}
		re, err := compileRegex(raw)
		if err != nil {
			return nil, err
		}
		return &MatchExpression{expr: RegexpMatchExpr{Pattern: raw, re: re}}, nil
	}
